starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "bucket_name" {
  description = "Input variable bucket_name."
  type        = string
  default     = "app-assets"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_s3_bucket" "this" {
  # TODO - Complete the bucket name expression.
  # Use a conditional expression so production keeps the base name and other environments get a suffix.
}
